const demo=!!window.PHARMA_DEMO, $id=id=>document.getElementById(id), money=n=>'৳'+Number(n).toLocaleString('en-US',{maximumFractionDigits:0}), num=n=>Number(n).toLocaleString('en-US'), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={dashboard:'Overview',forecast:'Demand forecast',sourcing:'Global sourcing',production:'Production & yield',inventory:'Depot inventory',audit:'Audit trail'};
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',forecast:'<path d="M3 18 9 12l4 3 8-11M3 3v18h18"/>',sourcing:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',production:'<path d="M3 21V9l6 3V6l6 5V3h5v18ZM6 17h2m3 0h2m3 0h2"/>',inventory:'<path d="m3 8 9-5 9 5v12H3ZM3 8h18M9 20v-7h6v7"/>',audit:'<path d="M7 3h10v3h3v15H4V6h3ZM7 3v5h10V3M8 12h8m-8 4h8"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7Z"/>',check:'<path d="m5 12 4 4 10-10"/>',box:'<path d="m3 7 9-4 9 4v10l-9 4-9-4ZM3 7l9 5 9-5M12 12v9"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${icons[k]||icons.box}</svg>`;
let state, current=location.hash.slice(1)||location.pathname.split('/')[1]||'dashboard', charts=[], lastForecast, filters={};
if(!paths[current]) current='dashboard';
const toast=s=>{const t=$id('toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',5500)};
const csrf=()=>document.cookie.split('; ').find(x=>x.startsWith('csrftoken='))?.split('=')[1];
async function api(path,data){const r=await fetch('/api/'+path+'/',{method:'POST',headers:{'Content-Type':'application/json','X-CSRFToken':csrf()},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw Error(typeof j==='object'?JSON.stringify(j):j);return j}
async function init(){try{state=demo?(JSON.parse(localStorage.getItem('pn-demo-v1')||'null')||await (await fetch('demo-data.json')).json()):await(await fetch('/api/state/')).json();render()}catch(e){$id('app').innerHTML='<div class="loading">Unable to load the workspace. Refresh after signing in.</div>';toast(e.message)}}
function persist(){if(demo)localStorage.setItem('pn-demo-v1',JSON.stringify(state))}
async function refresh(){if(!demo)state=await(await fetch('/api/state/')).json();persist();render()}
function navigate(page){current=page;location.hash=page;render()}
window.addEventListener('hashchange',()=>{let p=location.hash.slice(1);if(paths[p]&&current!==p){current=p;render()}});
function can(roles){return demo||state.admin||state.roles?.some(r=>roles.includes(r))}
function tag(s,c=''){return `<span class="tag ${c}">${esc(s)}</span>`}
function btn(label,fn,style='',ico=''){return `<button class="button ${style}" onclick="${fn}">${ico?icon(ico):''}${label}</button>`}
function stat(label,value,meta,ico='box',color=''){return `<div class="stat"><div class="label">${label}${icon(ico)}</div><div class="value ${color}">${value}</div><div class="meta">${meta}</div></div>`}
function table(headers,rows,id=''){return `<div class="table-wrap"><table ${id?`id="${id}"`:''}><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>'<tr>'+r.map(c=>`<td>${c}</td>`).join('')+'</tr>').join(''):`<tr><td colspan="${headers.length}" class="empty">No records to display</td></tr>`}</tbody></table></div>`}
function options(items,selected){return items.map(x=>`<option value="${x.id}" ${String(x.id)===String(selected)?'selected':''}>${esc(x.name)}</option>`).join('')}
function field(label,id,value,type='number',attrs=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${attrs}></div>`}
function select(label,id,opts){return `<div class="field"><label for="${id}">${label}</label><select id="${id}">${opts}</select></div>`}
function render(){charts.forEach(c=>c.destroy());charts=[];const title=paths[current];$id('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span>✣</span>PharmaNexus</div><div class="tagline">MARKETPULSE INTELLIGENCE</div><div class="nav-label">WORKSPACE</div><nav>${Object.entries(paths).map(([k,v])=>`<a href="#${k}" class="nav-item ${current===k?'active':''}" onclick="navigate('${k}')">${icon(k)}${v}${k==='inventory'?'<span class="badgenum">5</span>':''}</a>`).join('')}</nav><div class="sidebar-foot"><div class="workspace-card"><strong>Better decisions.<br>Less waste.</strong>Connected intelligence across your pharmaceutical supply chain.</div><div class="user"><span class="avatar">${demo?'MH':esc(state.user.slice(0,2).toUpperCase())}</span><div>${demo?'Monir Hossain':esc(state.user)}<small>${demo?'Demo workspace':esc(state.roles.join(' · '))}</small></div></div>${!demo?'<form method="post" action="/accounts/logout/"><input type="hidden" name="csrfmiddlewaretoken" value="'+csrf()+'"><button class="button small" style="margin-top:15px">Sign out</button></form>':''}</div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Workspace <b>/ &nbsp; ${title}</b></div><div class="top-actions"><span class="date">${new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}</span><span class="pill">${demo?'Interactive demo':'Connected workspace'}</span></div></header><div class="content"><div class="page-heading"><div><div class="eyebrow">PHARMACEUTICAL OPERATIONS</div><h1>${current==='dashboard'?'Your supply chain, in focus.':title}</h1><p class="subtitle">${{dashboard:'Turn operational signals into confident decisions.',forecast:'Understand demand. Plan the next 90 days.',sourcing:'The lowest price is not always the lowest cost.',production:'Protect potency, improve yield, reduce waste.',inventory:'The right stock, in the right depot, before expiry.',audit:'Every change has an owner, a timestamp and a reason.'}[current]}</p></div><div class="btns">${btn('Print report','window.print()','','audit')}${can(['Manager','Analyst','Auditor'])?btn(demo?'Export CSV':'Export Excel','exportData()','primary','download'):''}</div></div><div class="demo-banner"><span><strong>${demo?'SAMPLE DATA WORKSPACE':'SYNTHETIC TRAINING DATA'}</strong> &nbsp; ${demo?'Explore every module. Changes are saved in this browser only.':'Replace seeded data with validated operational records before use.'}</span>${demo?'<a href="#" onclick="resetDemo(event)">Reset demo</a>':'<span>BDT · Asia/Dhaka</span>'}</div><div id="view"></div><footer class="footer"><span>PharmaNexus · MarketPulse & Global Sourcing Intelligence</span><span>BDT currency · Synthetic data · ${num(state.row_count)} demand records</span></footer></div></main></div>`;({dashboard:dashboard,forecast:forecastPage,sourcing:sourcingPage,production:productionPage,inventory:inventoryPage,audit:auditPage})[current]()}
function chart(id,type,labels,datasets,extra={}){if(!window.Chart){$id(id).parentElement.innerHTML='<p class="note">Chart library unavailable. See the data tables below.</p>';return}charts.push(new Chart($id(id),{type,data:{labels,datasets},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},ticks:{maxTicksLimit:7,color:'#97a297',font:{size:10}}},y:{grid:{color:'#eef2eb'},border:{display:false},ticks:{color:'#97a297',font:{size:10}}}},...extra}}))}
function dashboard(){const stock=state.stocks.reduce((a,s)=>a+s.value,0),risk=state.stocks.filter(s=>s.days>0&&s.days<=60),waste=state.production.reduce((a,b)=>a+b.waste,0),pending=state.transfers.filter(t=>t.status==='pending'),yieldAvg=state.production.reduce((a,b)=>a+b.yield,0)/state.production.length;
 $id('view').innerHTML=`<div class="stat-grid">${stat('Inventory value',money(stock),'Across 5 distribution depots','inventory')}${stat('Near-expiry stock',money(risk.reduce((a,s)=>a+s.value,0)),'Retail value · expires within 60 days','clock','warning')}${stat('Average batch yield',yieldAvg.toFixed(1)+'%','Latest '+state.production.length+' production batches','production')}${stat('Transfer opportunity',money(pending.reduce((a,t)=>a+t.margin,0)),pending.length+' proposals awaiting approval','sourcing','good')}</div><div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>Demand at a glance</h2><p>Daily unit demand across all SKUs and depots</p></div><span class="pill">Last 90 days</span></div><div class="chart-box"><canvas id="demandChart"></canvas></div><div class="legend" style="margin-top:15px"><span><i></i>Recorded demand</span><span>Synthetic historical observations</span></div></section><section class="panel"><div class="panel-head"><h2>Signals worth your attention</h2>${tag('Intelligence')}</div><div class="insight"><div class="insight-title"><span class="square-icon">${icon('clock')}</span>Recover value before expiry</div><p>${pending.length?'Sylhet excess can help cover Chattogram demand before expiry.':'No pending transfers. Review forecast coverage for fresh opportunities.'}</p><a onclick="navigate('inventory')">Review transfer opportunities</a></div><div class="insight"><div class="insight-title"><span class="square-icon blue">${icon('production')}</span>Night-shift yield under pressure</div><p>Injected waste spikes on MX-03 are flagged by anomaly detection.</p><a onclick="navigate('production')">Investigate production batches</a></div><div class="insight"><div class="insight-title"><span class="square-icon green">${icon('sourcing')}</span>Purity changes the price ranking</div><p>Compare landed cost per effective kilogram before selecting a supplier.</p><a onclick="navigate('sourcing')">Compare supplier offers</a></div></section></div><div class="grid-equal"><section class="panel"><div class="panel-head"><div><h2>Depot stock health</h2><p>Unit balance by distribution location</p></div>${tag('5 depots','gray')}</div>${table(['Depot','Stock units','Near expiry','Health'],state.depots.map(d=>{const rows=state.stocks.filter(s=>s.depot_id===d.id),qty=rows.reduce((a,s)=>a+s.quantity,0),risk=rows.filter(s=>s.days<=60).reduce((a,s)=>a+s.quantity,0);return [`<strong>${esc(d.name)}</strong>`,num(qty),num(risk),`<div class="bar"><span style="width:${Math.max(5,100-risk/Math.max(qty,1)*100)}%"></span></div>`]}))}</section><section class="panel"><div class="panel-head"><div><h2>Global sourcing snapshot</h2><p>Paracetamol API · BDT per effective kg</p></div><a onclick="navigate('sourcing')" style="font-size:12px;cursor:pointer">View comparison</a></div>${table(['Country','Purity','True cost','Lead time'],state.sourcing.map((s,i)=>[`<strong>${esc(s.country)}</strong> ${i===0?tag('Best'):''}`,s.potency+'%',money(s.true_cost),s.lead_days+' days']))}</section></div><div class="callout"><div><h3>Plan ahead. Keep your network balanced.</h3><p>Explore a 90-day demand forecast with prescribing, seasonal and pricing scenarios.</p></div>${btn('Open demand forecast',"navigate('forecast')",'','forecast')}</div>`;
 chart('demandChart','line',state.history.map(x=>x.date.slice(5)),[{data:state.history.map(x=>x.units),borderColor:'#248a72',backgroundColor:'#248a7210',fill:true,tension:.35,pointRadius:0,borderWidth:2}]);}
function sourcingPage(){const cheapest=[...state.sourcing].sort((a,b)=>a.nominal-b.nominal)[0],best=state.sourcing[0];$id('view').innerHTML=`<div class="stat-grid">${stat('Best true cost',money(best.true_cost),esc(best.country)+' · purity-adjusted','sourcing','good')}${stat('Lowest nominal offer',money(cheapest.nominal),esc(cheapest.country)+' · before freight and duty','box')}${stat('Countries benchmarked',state.sourcing.length,'Same molecule · normalized kg units','sourcing')}${stat('Fastest lead time',Math.min(...state.sourcing.map(x=>x.lead_days))+' days','Supplier quoted · sample data','clock')}</div><section class="panel"><div class="panel-head"><div><h2>Country / supplier benchmark</h2><p>Paracetamol API · BDT/kg · true cost = landed cost × 100 ÷ potency</p></div>${tag('Ranked by true cost')}</div>${table(['Supplier / country','Nominal price','Landed cost','Potency','True cost','Lead time'],state.sourcing.map((s,i)=>[`<strong>${esc(s.supplier)}</strong><div class="table-sub">${esc(s.country)} ${i===0?'· BEST VALUE':''}</div>`,money(s.nominal),money(s.landed),s.potency+'%',`<strong>${money(s.true_cost)}</strong>`,s.lead_days+' days']))}<p class="note">Landed cost includes freight and duty. Offers are synthetic, not current supplier quotations.</p></section><div class="grid-equal section-gap"><section class="panel"><div class="panel-head"><div><h2>Live potency calculator</h2><p>Adjust input quantity to the lot’s measured potency</p></div>${icon('production')}</div><div class="filters">${field('Standard API quantity (kg)','standard',100,'number','min="0.001" step="0.001" oninput="calc()"')}${field('Lot potency (%)','potency',95,'number','min="0.001" max="100" step="0.01" oninput="calc()"')}</div><div class="calculator-result"><small>ADJUSTED API REQUIRED</small><strong id="adjusted">105.2632 kg</strong><small id="calcNote">Additional input: 5.2632 kg</small></div><p class="note">Calculation aid only. Manufacturing release still requires approved specifications and laboratory verification.</p></section><section class="panel"><div class="panel-head"><div><h2>Export price intelligence</h2><p>Paracetamol 500 mg · normalized price per unit</p></div>${tag('Illustrative','gray')}</div>${table(['Market','Unit price','vs. home price'],state.benchmarks.map(b=>[`<strong>${esc(b.country)}</strong>`,money(b.unit_price_bdt),tag(((b.unit_price_bdt/20-1)*100).toFixed(0)+'%',b.unit_price_bdt<20?'amber':'gray')]))}<p class="note">Not adjusted for tax, registration, pack size or channel margin. Validate comparability before export decisions.</p></section></div>`}
let calcTimer;function calc(){clearTimeout(calcTimer);calcTimer=setTimeout(async()=>{try{let a=Number($id('standard').value),p=Number($id('potency').value);if(a<=0||p<=0||p>100)throw Error('Enter positive API and potency between 0 and 100%.');let v;if(demo)v=a*100/p;else v=(await $.ajax({url:'/api/potency/',method:'POST',headers:{'X-CSRFToken':csrf()},contentType:'application/json',data:JSON.stringify({standard:a,potency:p})})).adjusted;$id('adjusted').textContent=v.toFixed(4)+' kg';$id('calcNote').textContent='Additional input: '+(v-a).toFixed(4)+' kg'}catch(e){$id('adjusted').textContent='Check inputs';$id('calcNote').textContent=e.message}},180)}
function forecastPage(){$id('view').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Forecast workspace</h2><p>${demo?'Precomputed model baseline with interactive scenario simulation':'Random Forest regression · chronological 30-day holdout validation'}</p></div>${tag('90-day horizon')}</div><div class="filters">${select('Product / SKU','forecastSku',options(state.skus,filters.sku||1))}${select('Distribution depot','forecastDepot',options(state.depots,filters.depot||1))}${field('Rx trend multiplier','rx',1,'number','min="0.2" max="2" step="0.05"')}${field('Regulatory multiplier','reg',1,'number','min="0.2" max="2" step="0.05"')}${field('Competitor price index','comp',1,'number','min="0.2" max="2" step="0.05"')}</div><div class="filters">${field('Holiday dates (comma-separated YYYY-MM-DD)','holiday','','text','placeholder="2027-01-01, 2027-02-21"')}${btn('Run forecast','runForecast()','primary','forecast')}</div><p class="note">External drivers are scenario assumptions. Seasonal disease patterns are learned from historical observations. Regulatory changes are manually encoded; no live DGDA, FDA, MHRA or ANVISA feed is connected.</p></section><div id="forecastResult" class="section-gap"><div class="panel empty">Choose a SKU and depot, then run a forecast.</div></div>`;runForecast()}
async function runForecast(){try{const sku=+$id('forecastSku').value,depot=+$id('forecastDepot').value,rx=+$id('rx').value,regulatory=+$id('reg').value,competitor=+$id('comp').value,holiday_dates=$id('holiday').value.split(',').map(x=>x.trim()).filter(Boolean);if([rx,regulatory,competitor].some(x=>x<.2||x>2))throw Error('Scenario multipliers must be between 0.2 and 2.');if(holiday_dates.some(x=>!/^\d{4}-\d{2}-\d{2}$/.test(x)||isNaN(Date.parse(x))))throw Error('Use YYYY-MM-DD holiday dates.');filters={sku,depot};$id('forecastResult').innerHTML='<div class="panel empty">Training model and evaluating demand…</div>';let f;if(demo){f=structuredClone(state.forecasts[`${sku}-${depot}`]);f.daily=f.daily.map(x=>({...x,units:Math.round(x.units*rx*regulatory/competitor*(holiday_dates.includes(x.date)?1.3:1))}));f.total=f.daily.reduce((a,x)=>a+x.units,0);f.simulated=true}else f=await api('forecast',{sku,depot,rx,regulatory,competitor,holiday_dates});lastForecast=f;showForecast(f)}catch(e){toast(e.message);$id('forecastResult').innerHTML='<div class="panel empty">Forecast could not run. Check the inputs and try again.</div>'}}
function showForecast(f){charts.forEach(c=>c.destroy());charts=[];const cmp=(k,label)=>stat(label,(f[k].change_pct===null?'—':(f[k].change_pct>0?'+':'')+f[k].change_pct+'%'),num(f[k].current)+' vs. '+num(f[k].previous)+' units','forecast',f[k].change_pct>=0?'good':'warning');$id('forecastResult').innerHTML=`<div class="stat-grid">${stat('90-day forecast',num(f.total),'Estimated units · scenario dependent','forecast')}${cmp('wow','Week over week')}${cmp('mom','Month to date vs. prior month')}${cmp('sply','Same period last year')}</div><div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>Demand outlook</h2><p>Historical observations and next 90 days</p></div>${tag(f.simulated?'Scenario simulation':'Model prediction')}</div><div class="chart-box"><canvas id="forecastChart"></canvas></div><div class="legend" style="margin-top:15px"><span><i></i>Actual</span><span><i class="pale"></i>Forecast</span></div><p class="note">Holdout MAE: ${f.mae} units/day · ${num(f.training_rows)} training observations · As of ${esc(f.as_of)}. ${demo?'Scenario sliders scale a precomputed forecast; the downloadable Django app retrains the model.':''}</p></section><section class="panel"><div class="panel-head"><h2>What drives the model</h2></div>${f.importance.slice(0,6).map(x=>`<div class="importance"><span>${esc(x.feature.replaceAll('_',' '))}</span><div class="bar"><span style="width:${x.importance}%"></span></div><b>${x.importance}%</b></div>`).join('')}<p class="note">Feature importance measures model influence, not causality. Random forests may understate trends beyond their training range.</p></section></div><div class="grid-equal"><section class="panel"><h2>Day and holiday patterns</h2>${Number(filters.sku)===8?'<p class="note warning">Rx watch: the seeded azithromycin series includes a declining prescribing trend. Review the assumptions before replenishment.</p>':''}${table(['Pattern','Average units / day'],[['Weekday (Sun–Thu)',num(f.patterns.weekday_mean)],['Weekend (Fri–Sat)',num(f.patterns.weekend_mean)],['Holiday observations',num(f.patterns.holiday_mean||0)]])}<p class="note">Seeded holiday windows are illustrative, not an authoritative calendar.</p></section><section class="panel"><h2>Forecast schedule</h2>${table(['Date','Predicted units'],f.daily.slice(0,7).map(x=>[esc(x.date),num(x.units)]))}${btn('Download all 90 days','exportForecast()','small')}</section></div>`;const hist=f.history.slice(-30);chart('forecastChart','line',[...hist.map(x=>x.date.slice(5)),...f.daily.map(x=>x.date.slice(5))],[{data:[...hist.map(x=>x.units),...f.daily.map(()=>null)],borderColor:'#1c8a72',pointRadius:0,tension:.3,borderWidth:2},{data:[...hist.map(()=>null),...f.daily.map(x=>x.units)],borderColor:'#a8c979',backgroundColor:'#d1e6ad20',fill:true,pointRadius:0,tension:.3,borderWidth:2}])}
function productionPage(){const anomalies=state.production.filter(x=>x.anomaly);$id('view').innerHTML=`<div class="stat-grid">${stat('Production batches',num(state.production.length),'Latest recorded batches','production')}${stat('Waste cost',money(state.production.reduce((a,b)=>a+b.waste,0)),'Across displayed batches','box','warning')}${stat('Anomaly flags',anomalies.length,'Isolation Forest · 10% contamination','bolt','warning')}${stat('Average potency',(state.production.reduce((a,b)=>a+b.potency,0)/state.production.length).toFixed(1)+'%','Measured API lot potency','production')}</div><div class="grid-equal"><section class="panel"><div class="panel-head"><h2>Yield by shift</h2>${tag('Production analytics')}</div><div class="chart-box"><canvas id="yieldChart"></canvas></div></section><section class="panel"><div class="panel-head"><h2>Investigation note</h2>${tag('Action required','amber')}</div><h3>MX-03 · Night shift</h3><p class="note">The synthetic dataset includes recurring night-shift waste spikes. The detector evaluates yield, waste per planned unit, shift and machine indicators.</p><p class="note">An anomaly is an investigation flag, not an automatic batch rejection. Record the root cause and review operating conditions with the production team.</p>${can(['Production','Manager'])?'<div class="section-gap">'+btn('Record production batch','batchDialog()','primary','production')+'</div>':''}</section></div><section class="panel"><div class="panel-head"><div><h2>Batch performance register</h2><p>Search by product, machine, shift or date</p></div></div>${table(['Batch / SKU','Date','Machine','Shift','Yield','Waste cost','Adjusted API','Review'],state.production.map(b=>[`<strong>PB-${String(b.id).padStart(4,'0')}</strong><div class="table-sub">${esc(b.sku)}</div>`,b.date,esc(b.machine),esc(b.shift),b.yield+'%',money(b.waste),b.adjusted_api.toFixed(2)+' kg',tag(b.anomaly?'Investigate':'Normal',b.anomaly?'amber':'')]),'productionTable')}</section>`;const groups=['Day','Night'];chart('yieldChart','bar',groups,[{data:groups.map(g=>{let b=state.production.filter(x=>x.shift===g);return b.reduce((a,x)=>a+x.yield,0)/b.length}),backgroundColor:['#258671','#d8b76b'],borderRadius:7,barThickness:65}],{scales:{y:{min:70,max:100,ticks:{callback:v=>v+'%'},grid:{color:'#eef2eb'}},x:{grid:{display:false}}}});enhance('productionTable')}
function inventoryPage(){const stocks=state.stocks.filter(s=>s.quantity>0),pending=state.transfers.filter(t=>t.status==='pending');$id('view').innerHTML=`<div class="stat-grid">${stat('Available units',num(stocks.reduce((a,s)=>a+s.quantity,0)),'All depots · includes expiry-risk stock','inventory')}${stat('Near-expiry lots',stocks.filter(s=>s.days>0&&s.days<=60).length,'Within the next 60 days','clock','warning')}${stat('Pending transfers',pending.length,'Awaiting manager approval','sourcing')}${stat('Potential contribution',money(pending.reduce((a,t)=>a+t.margin,0)),'After product cost and estimated logistics','box','good')}</div><section class="panel"><div class="panel-head"><div><h2>Revenue recovery opportunities</h2><p>Demand-informed transfers · 2 days transit · ৳2/unit + ৳500 logistics</p></div><div class="btns">${can(['Manager','Analyst'])?btn('Find opportunities','recommendDialog()','small','bolt'):''}${can(['Manager','Warehouse'])?btn('Issue stock (FEFO)','issueDialog()','small primary','inventory'):''}</div></div>${table(['Product','From / to','Quantity','Est. contribution','Status','Action'],state.transfers.map(t=>[`<strong>${esc(t.sku)}</strong>`,`${esc(t.source)} / ${esc(t.destination)}`,num(t.quantity),money(t.margin),tag(t.status,t.status==='pending'?'amber':''),t.status==='pending'&&can(['Manager'])?btn('Approve',`approveDialog(${t.id})`,'small primary'):tag('Recorded','gray')]))}<p class="note">Estimated contribution is not realized revenue. Verify quality release, destination demand and transport conditions before approval.</p></section><section class="panel section-gap"><div class="panel-head"><div><h2>Depot lot register</h2><p>Expiry-aware inventory · FEFO excludes stock expiring today or earlier</p></div>${tag('Batch traceability','gray')}</div>${table(['Product / batch','Depot','Expiry date','Days left','Units','Retail value','Status'],state.stocks.map(s=>[`<strong>${esc(s.sku)}</strong><div class="table-sub">${esc(s.batch)}</div>`,esc(s.depot),s.expiry,s.days,num(s.quantity),money(s.quantity*(state.skus.find(x=>x.id===s.sku_id)?.unit_price||0)),tag(s.quantity===0?'Out of stock':s.days<=0?'Expired':s.days<=60?'Near expiry':'Healthy',s.quantity===0||s.days<=0?'red':s.days<=60?'amber':'')]),'inventoryTable')}</section>`;enhance('inventoryTable')}
function auditPage(){$id('view').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Accountability, by design</h2><p>Mandatory reasons, role checks and append-only records in the Django application.</p></div>${tag(demo?'Browser demo':'Append-only',demo?'amber':'')}</div><p class="note" style="margin-top:0">${demo?'Demo history is editable through browser storage and is not an immutable audit system.':'Database triggers prevent UPDATE and DELETE of audit records. Database administrators remain a privileged trust boundary.'} This application is not certified for 21 CFR Part 11; electronic signatures, validated procedures and operational controls require separate implementation and validation.</p></section><section class="panel section-gap"><div class="panel-head"><div><h2>Audit event history</h2><p>Latest 200 events · UTC timestamps</p></div>${tag(state.audit.length+' events','gray')}</div>${table(['Event / entity','Actor','UTC timestamp','Reason','Change details'],state.audit.map(a=>[`<strong>${esc(a.action)}</strong><div class="table-sub">${esc(a.entity)}</div>`,esc(a.actor),esc(a.timestamp.replace('T',' ').slice(0,19)),esc(a.reason),`<details><summary>View changes</summary><pre class="audit-detail">${esc(JSON.stringify({before:a.old,after:a.new},null,2))}</pre></details>`]),'auditTable')}</section>`;enhance('auditTable')}
function enhance(id){if(window.DataTable)new DataTable('#'+id,{pageLength:10,order:[],lengthChange:false,language:{search:'Search records:'}})}
function openDialog(title,body,onSubmit){const d=$id('dialog');d.innerHTML=`<form id="modalForm"><h2>${title}</h2>${body}<div class="dialog-error" id="dialogError"></div><div class="btns">${btn('Cancel',"document.getElementById('dialog').close();return false") }<button class="button primary" type="submit">Confirm</button></div></form>`;d.showModal();$id('modalForm').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;try{submit.disabled=true;await onSubmit();d.close();await refresh()}catch(err){$id('dialogError').textContent=err.message}finally{submit.disabled=false}}}
const reasonField=()=>field('Reason (required)','reason','','text','required minlength="3" maxlength="1000" placeholder="Explain the operational decision"');
function log(action,entity,old,newValue,reason){state.audit.unshift({id:Date.now(),action,entity,old,new:newValue,reason,actor:'Demo manager',timestamp:new Date().toISOString()})}
function approveDialog(id){let t=state.transfers.find(x=>x.id===id);openDialog('Approve depot transfer',`<p>Move <b>${num(t.quantity)}</b> units of ${esc(t.sku)} from ${esc(t.source)} to ${esc(t.destination)}.</p>${reasonField()}`,async()=>{let reason=$id('reason').value.trim();if(reason.length<3)throw Error('Please provide a reason.');if(demo){if(t.status!=='pending')throw Error('Transfer already approved.');let source=state.stocks.find(s=>s.id===t.lot);if(source.quantity<t.quantity)throw Error('Insufficient source stock.');if(source.days<=0)throw Error('This lot has expired.');let dest=state.stocks.find(s=>s.batch===source.batch&&s.depot===t.destination);if(!dest){const depot=state.depots.find(d=>d.name===t.destination);dest={...source,id:Date.now(),depot_id:depot.id,depot:depot.name,quantity:0,value:0};state.stocks.push(dest)}const before={source:source.quantity,destination:dest.quantity};source.quantity-=t.quantity;dest.quantity+=t.quantity;t.status='approved';syncValues();log('Transfer approved','Transfer:'+id,before,{source:source.quantity,destination:dest.quantity},reason)}else await api('transfers/'+id+'/approve',{reason});toast('Transfer approved. Both depot balances updated.')})}
function syncValues(){state.stocks.forEach(s=>s.value=s.quantity*Number(state.skus.find(x=>x.id===s.sku_id).unit_price))}
function issueDialog(){openDialog('Issue stock using FEFO',`${select('Product','issueSku',options(state.skus,1))}${select('Depot','issueDepot',options(state.depots,1))}${field('Quantity (units)','issueQty',100,'number','required min="1" step="1"')}${reasonField()}<p class="note">Earliest-expiring unexpired lots are deducted first. The whole issue is rejected if stock is insufficient.</p>`,async()=>{const sku=+$id('issueSku').value,depot=+$id('issueDepot').value,quantity=+$id('issueQty').value,reason=$id('reason').value.trim();if(!Number.isInteger(quantity)||quantity<=0||reason.length<3)throw Error('Enter a positive whole quantity and a reason.');if(demo){let lots=state.stocks.filter(s=>s.sku_id===sku&&s.depot_id===depot&&s.days>0&&s.quantity>0).sort((a,b)=>a.expiry.localeCompare(b.expiry)||a.id-b.id);if(lots.reduce((a,s)=>a+s.quantity,0)<quantity)throw Error('Insufficient unexpired stock.');let left=quantity;for(const lot of lots){let take=Math.min(left,lot.quantity);if(!take)break;const old=lot.quantity;lot.quantity-=take;left-=take;log('FEFO deduction','StockLot:'+lot.id,{quantity:old},{quantity:lot.quantity},reason)}syncValues()}else await api('deduct',{sku,depot,quantity,reason});toast('Stock issued using earliest expiry first.')})}
function recommendDialog(){openDialog('Find recovery opportunities',`${reasonField()}<p class="note">Checks 90-day forecasts against near-expiry stock and destination coverage. Existing pending proposals are preserved.</p>`,async()=>{const reason=$id('reason').value.trim();if(reason.length<3)throw Error('Please provide a reason.');if(demo){let added=0;for(const lot of state.stocks.filter(s=>s.days>2&&s.days<=90&&s.quantity>0)){if(state.transfers.some(t=>t.lot===lot.id&&t.status==='pending'))continue;const f=state.forecasts[`${lot.sku_id}-${lot.depot_id}`];let excess=Math.max(0,lot.quantity-f.daily.slice(0,lot.days).reduce((a,x)=>a+x.units,0));for(const depot of state.depots.filter(d=>d.id!==lot.depot_id)){if(!excess)break;let forecast=state.forecasts[`${lot.sku_id}-${depot.id}`].daily.slice(0,lot.days-2).reduce((a,x)=>a+x.units,0),stock=state.stocks.filter(s=>s.sku_id===lot.sku_id&&s.depot_id===depot.id&&s.days>0).reduce((a,s)=>a+s.quantity,0),inbound=state.transfers.filter(t=>t.sku===lot.sku&&t.destination===depot.name&&t.status==='pending').reduce((a,t)=>a+t.quantity,0),qty=Math.min(excess,Math.max(0,forecast-stock-inbound)),sku=state.skus.find(s=>s.id===lot.sku_id),margin=qty*(sku.unit_price-sku.unit_cost-2)-500;if(qty>0&&margin>0){let t={id:Date.now()+added++,sku:lot.sku,source:lot.depot,destination:depot.name,quantity:qty,margin,status:'pending',lot:lot.id};state.transfers.unshift(t);excess-=qty;log('Transfer proposed','Transfer:'+t.id,{},t,reason)}}}toast(added+' new transfer opportunities found.')}else{const r=await api('recommend',{reason});toast(r.created.length+' new transfer opportunities found.')}})}
function batchDialog(){openDialog('Record a production batch',`${select('Product','batchSku',options(state.skus,1))}<div class="filters">${field('Date','batchDate',new Date().toISOString().slice(0,10),'date','required')}${select('Shift','batchShift','<option>Day</option><option>Night</option>')}${select('Machine','batchMachine','<option>MX-01</option><option>MX-02</option><option>MX-03</option>')}</div><div class="filters">${field('Standard API (kg)','batchApi',100,'number','required min="0.001" step="0.001"')}${field('Potency (%)','batchPotency',98,'number','required min="0.001" max="100" step="0.001"')}</div><div class="filters">${field('Planned units','batchPlanned',10000,'number','required min="1"')}${field('Actual units','batchActual',9800,'number','required min="0"')}${field('Waste cost (BDT)','batchWaste',2400,'number','required min="0" step="0.01"')}</div>${reasonField()}`,async()=>{const d={sku:+$id('batchSku').value,date:$id('batchDate').value,shift:$id('batchShift').value,machine:$id('batchMachine').value,standard_api:+$id('batchApi').value,potency_pct:+$id('batchPotency').value,planned_units:+$id('batchPlanned').value,actual_units:+$id('batchActual').value,waste_cost_bdt:+$id('batchWaste').value,reason:$id('reason').value.trim()};if(d.actual_units>d.planned_units)throw Error('Actual units cannot exceed planned units.');if(d.reason.length<3)throw Error('Please provide a reason.');if(demo){let b={id:Date.now(),sku:state.skus.find(x=>x.id===d.sku).name,date:d.date,machine:d.machine,shift:d.shift,yield:Math.round(d.actual_units/d.planned_units*10000)/100,waste:d.waste_cost_bdt,potency:d.potency_pct,adjusted_api:d.standard_api*100/d.potency_pct,anomaly:d.actual_units/d.planned_units<.9};state.production.unshift(b);log('Batch recorded','ProductionBatch:'+b.id,{},d,d.reason)}else await api('production',d);toast('Production batch recorded. Demo flags use a yield threshold; Django reruns anomaly detection.')})}
function download(name,text,type='text/csv'){let a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csv(rows){if(!rows.length)return 'No records';let keys=Object.keys(rows[0]);return [keys,...rows.map(r=>keys.map(k=>{let v=typeof r[k]==='object'?JSON.stringify(r[k]):String(r[k]??'');return /^[=+\-@]/.test(v)?"'"+v:v}))].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n')}
function exportData(){if(!demo){location.href='/api/export/';return}const rows=({dashboard:state.stocks,inventory:state.stocks,sourcing:state.sourcing,production:state.production,audit:state.audit,forecast:lastForecast?.daily||[]})[current];download('PharmaNexus-'+current+'.csv',csv(rows));toast('CSV exported. Multi-sheet Excel is available in the Django application.')}
function exportForecast(){if(lastForecast)download('PharmaNexus-90-day-forecast.csv',csv(lastForecast.daily))}
function resetDemo(e){e.preventDefault();openDialog('Reset sample workspace','<p>This restores the original sample data and removes changes made in this browser.</p>',async()=>{localStorage.removeItem('pn-demo-v1');state=await(await fetch('demo-data.json')).json();lastForecast=null;toast('Sample workspace restored.')})}
init();
